export function Crud({
  heading = "{{heading}}",
  mode = "{{mode}}",
  accent = "{{accent}}",
  showDelete = {{showDelete}},
  recordName = "{{recordName}}",
}) {
  const current = mode !== "create";
  return (
    <section aria-label={heading} style={{ fontFamily: "system-ui, sans-serif", fontSize: 13.5, color: "#241430", background: "#FAF7F2", maxWidth: 420, width: 420, padding: 16, borderRadius: 12, boxSizing: "border-box" }}>
      <h3 style={{ margin: "0 0 10px", fontSize: 15, fontWeight: 700 }}>{heading}</h3>
      <div style={{ display: "flex", gap: 12 }}>
        <ul aria-label="Records" style={{ listStyle: "none", margin: 0, padding: 0, flex: "0 0 120px" }}>
          <li aria-current={current ? "true" : undefined} style={{ padding: "7px 8px", borderRadius: 6, background: current ? accent : "transparent", fontWeight: current ? 700 : 400 }}>{recordName}</li>
          <li style={{ padding: "7px 8px", borderRadius: 6 }}>Priya Nair</li>
          <li style={{ padding: "7px 8px", borderRadius: 6 }}>Sam Okoro</li>
        </ul>
        {mode !== "list" && (
          <form aria-label="Record details" style={{ flex: 1, background: "#fff", borderRadius: 8, padding: 12 }}>
            <label style={{ display: "block", fontSize: 11, fontWeight: 600, color: "#241430a0", marginBottom: 8 }}>Name
              <input type="text" defaultValue={recordName} style={{ display: "block", width: "100%", boxSizing: "border-box", marginTop: 3, padding: "6px 8px", border: "1px solid #24143030", borderRadius: 6, font: "inherit", color: "#241430" }} />
            </label>
            <label style={{ display: "block", fontSize: 11, fontWeight: 600, color: "#241430a0", marginBottom: 8 }}>Email
              <input type="text" defaultValue="jordan@example.com" style={{ display: "block", width: "100%", boxSizing: "border-box", marginTop: 3, padding: "6px 8px", border: "1px solid #24143030", borderRadius: 6, font: "inherit", color: "#241430" }} />
            </label>
            <div style={{ display: "flex", gap: 8, marginTop: 6 }}>
              <button type="submit" style={{ background: accent, border: "none", borderRadius: 6, padding: "6px 12px", font: "inherit", fontWeight: 700, cursor: "pointer" }}>Save</button>
              {showDelete && mode !== "create" && (
                <button type="button" style={{ background: "transparent", border: "1.5px solid #B3261E", color: "#B3261E", borderRadius: 6, padding: "6px 12px", font: "inherit", fontWeight: 700, cursor: "pointer" }}>Delete</button>
              )}
            </div>
          </form>
        )}
      </div>
    </section>
  );
}
